###The instruction to evaluate:
 Compare and contrast some common sorting algorithms such as bubble sort, insertion sort, selection sort, merge sort, quick sort, and heap sort. Analyze their time and space complexities using the big-O notation and show me the a easy C++ code example for each one.

###Response to evaluate:
Sure, here is a comparison of some common sorting algorithms and their time and space complexities, as well as an example implementation in C++ for each:

1. Bubble Sort: This algorithm repeatedly compares adjacent elements in an array and swaps them if they are in the wrong order, until the array is sorted.

Time Complexity: O(n^2)
Space Complexity: O(1)

Example C++ Code:

```
void bubbleSort(int arr[], int n) {
  bool isSwapped;
  for(int i = 0; i < n-1; i++) {
    isSwapped = false;
    for (int j = 0; j < n-i-1; j++) {
      if (arr[j] > arr[j+1]) {
        swap(arr[j], arr[j+1]);
        isSwapped = true;
      }
    }
    // If no two elements were swapped by inner loop, then break
    if (isSwapped == false)
        break;
  }
}
```

2. Insertion Sort: This algorithm iteratively inserts each element in an unsorted array into its correct position in a sorted subarray.

Time Complexity: O(n^2)
Space Complexity: O(1)

Example C++ Code:

```
void insertionSort(int arr[], int n) {
  for(int i = 1; i < n; i++) {
    int key = arr[i];
    int j = i-1;
    while(j >= 0 && arr[j] > key) {
      arr[j+1] = arr[j];
      j--;
    }
    arr[j+1] = key;
  }
}
```

3. Selection Sort: This algorithm iteratively finds the minimum value in an unsorted array and swaps it with the first element, then finds the minimum of the remaining elements and swaps it with the second element, and so on, until the array is sorted.

Time Complexity: O(n^2)
Space Complexity: O(1)

Example C++ Code:

```
void selectionSort(int arr[], int n) {
  int min_idx;
  for(int i = 0; i < n-1; i++) {
    min_idx = i;
    for(int j = i+1; j < n; j++) {
      if(arr[j] < arr[min_idx])
        min_idx = j;
    }
    swap(arr[min_idx], arr[i]);
  }
}
```

4. Merge Sort: This algorithm recursively divides an array in half, sorts each half using merge sort, and then merges the two halves together in sorted order.

Time Complexity: O(nlogn)
Space Complexity: O(n)

Example C++ Code:

```
void merge(int arr[], int l, int m, int r) {
  int i, j, k;
  int n1 = m - l + 1;
  int n2 = r - m;

  int L[n1], R[n2];

  for (i = 0; i < n1; i++)
    L[i] = arr[l + i];
  for (j = 0; j < n2; j++)
    R[j] = arr[m + 1 + j];

  i = 0;
  j = 0;
  k = l;
  while (i < n1 && j < n2) {
    if (L[i] <= R[j]) {
      arr[k] = L[i];
      i++;
    } else {
      arr[k] = R[j];
      j++;
    }
    k++;
  }

  while (i < n1) {
    arr[k] = L[i];
    i++;
    k++;
  }

  while (j < n2) {
    arr[k] = R[j];
    j++;
    k++;
  }
}

void mergeSort(int arr[], int l, int r) {
  if (l < r) {
    int m = l + (r - l) / 2;

    mergeSort(arr, l, m);
    mergeSort(arr, m + 1, r);
    merge(arr, l, m, r);
  }
}
```

5. Quick Sort: This algorithm selects a pivot element and partitions the array into two subarrays: elements less than the pivot and elements greater than the pivot. It then recursively sorts each subarray using quick sort.

Time Complexity: O(nlogn) on average (worst case O(n^2))
Space Complexity: O(logn)

Example C++ Code:

```
int partition(int arr[], int low, int high) {
  int pivot = arr[high];
  int i = low - 1;
  for(int j = low; j <= high-1; j++) {
    if(arr[j] <= pivot) {
      i++;
      swap(arr[i], arr[j]);
    }
  }
  swap(arr[i+1], arr[high]);
  return i+1;
}

void quickSort(int arr[], int low, int high) {
  if(low < high) {
    int pi = partition(arr, low, high);
    quickSort(arr, low, pi-1);
    quickSort(arr, pi+1, high);
  }
}
```

6. Heap Sort: This algorithm constructs a max heap from the array and then repeatedly extracts the maximum element from the heap and swaps it with the last element in the remaining heap, until the heap is empty and the array is sorted.

Time Complexity: O(nlogn)
Space Complexity: O(1)

Example C++ Code:

```
void heapify(int arr[], int n, int i) {
  int largest = i; 
  int l = 2*i + 1; 
  int r = 2*i + 2; 

  if (l < n && arr[l] > arr[largest])
    largest = l;

  if (r < n && arr[r] > arr[largest])
    largest = r;

  if (largest != i) {
    swap(arr[i], arr[largest]);
    heapify(arr, n, largest);
  }
}

void heapSort(int arr[], int n) {
  for(int i = n/2 - 1; i >= 0; i--)
    heapify(arr, n , i);

  for(int i = n-1; i > 0; i--) {
    swap(arr[0], arr[i]);
    heapify(arr, i, 0);
  }
}
```

